`buildRemoteRepositories()` iterates `settings?.repositories`, but Maven `Settings` does not expose repositories directly (they’re defined under profiles). In Groovy this will raise a `MissingPropertyException` at runtime when settings is non-null. Please extract repositories from `settings.profiles` / `settings.activeProfiles` (and apply mirrors/proxies), or remove this settings-based repo block.
```suggestion
        Set<String> seenRepositoryKeys = [] as Set<String>

        // Add Maven Central as default
        repos.add(new RemoteRepository.Builder('central', 'default',
            'https://repo.maven.apache.org/maven2/').build())
        seenRepositoryKeys << 'central|https://repo.maven.apache.org/maven2/'
        attemptedRepos << 'https://repo.maven.apache.org/maven2/'

        // Add repositories from active settings.xml profiles
        activeSettingsProfiles().each { profile ->
            profile.repositories?.each { repo ->
                def mirror = findMatchingMirror(repo.id as String)
                String effectiveRepoId = (mirror?.id ?: repo.id) as String
                String effectiveRepoUrl = (mirror?.url ?: repo.url) as String
                String repositoryKey = "${effectiveRepoId}|${effectiveRepoUrl}"

                if (seenRepositoryKeys.contains(repositoryKey)) {
                    return
                }

                RemoteRepository.Builder builder = new RemoteRepository.Builder(
                    effectiveRepoId, 'default', effectiveRepoUrl)

                def authentication = buildRepositoryAuthentication(effectiveRepoId)
                if (authentication != null) {
                    builder.setAuthentication(authentication)
                }

                def proxy = buildActiveProxy()
                if (proxy != null) {
                    builder.setProxy(proxy)
                }

                repos.add(builder.build())
                seenRepositoryKeys << repositoryKey
                attemptedRepos << effectiveRepoUrl
            }
        }

        return repos
    }

    private List activeSettingsProfiles() {
        if (!settings) {
            return []
        }

        List<String> activeProfileIds = settings.activeProfiles ?: []
        if (activeProfileIds) {
            return settings.profiles?.findAll { profile ->
                activeProfileIds.contains(profile.id)
            } ?: []
        }

        return settings.profiles?.findAll { profile ->
            profile.activation?.activeByDefault
        } ?: []
    }

    private def findMatchingMirror(String repositoryId) {
        settings?.mirrors?.find { mirror ->
            mirrorMatchesRepository(mirror.mirrorOf as String, repositoryId)
        }
    }

    private boolean mirrorMatchesRepository(String mirrorOf, String repositoryId) {
        if (!mirrorOf || !repositoryId) {
            return false
        }

        List<String> entries = mirrorOf.split(',')*.trim().findAll { it }
        boolean included = false

        entries.each { entry ->
            if (entry.startsWith('!')) {
                if (repositoryId == entry.substring(1)) {
                    included = false
                }
                return
            }

            if (entry == '*' || entry == repositoryId) {
                included = true
            }
        }

        return included
    }

    private def buildRepositoryAuthentication(String repositoryId) {
        def server = settings?.servers?.find { it.id == repositoryId }
        if (!server?.username || !server?.password) {
            return null
        }

        return new AuthenticationBuilder()
            .addUsername(server.username)
            .addPassword(server.password)
            .build()
    }

    private org.eclipse.aether.repository.Proxy buildActiveProxy() {
        def activeProxy = settings?.proxies?.find { it.active }
        if (!activeProxy?.host || !activeProxy?.port) {
            return null
        }

        def proxyAuthentication = null
        if (activeProxy.username && activeProxy.password) {
            proxyAuthentication = new AuthenticationBuilder()
                .addUsername(activeProxy.username)
                .addPassword(activeProxy.password)
                .build()
        }

        return new org.eclipse.aether.repository.Proxy(
            (activeProxy.protocol ?: 'http') as String,
            activeProxy.host as String,
            activeProxy.port as int,
            proxyAuthentication)
    }

